// Exact identities and parent chains from TeknoNaomi's retained catalog.
// Grouping does not qualify a game or change its persistent profile identity.
namespace TeknoParrotUi.Common
{
    public static partial class ArcadeGameRevisions
    {
        public static string PreviousTeknoNaomiControlName(GameProfile profile, string name)
        {
            if (profile?.EmulatorType != EmulatorType.TeknoNaomi ||
                (profile.GameVersion != "kofnw" && profile.GameVersion != "kofnwj")) return null;
            // Cabinet/JAMMA order, not the manual's separate panel-position numbers.
            var actions = new[] { "Light Punch", "Strong Punch", "Light Kick", "Strong Kick", "Heat" };
            for (var player = 1; player <= 2; ++player)
                for (var button = 0; button < actions.Length; ++button)
                    if (name == "P" + player + " " + actions[button])
                        return "P" + player + " Digital Button " + (button + 1);
            return null;
        }

